#!/bin/sh
# 调试利器：-n 只预览不执行，-B 无条件全部重建
# 期望输出见 expected_output（本机 MinGW 工具链 + GNU Make 真实执行捕获）

cat > Makefile << 'EOF'
CC := D:/mingw64/bin/gcc.exe
CFLAGS := -std=c11 -O2 -Wall
TARGET := app.exe
OBJS := main.o util.o

$(TARGET): $(OBJS)
	$(CC) $(CFLAGS) -o $@ $^

%.o: %.c
	$(CC) $(CFLAGS) -c $< -o $@

.PHONY: clean status
clean:
	@rm -f $(TARGET) $(OBJS)

status:
	@echo "artifacts: [$(wildcard *.o)] [$(wildcard *.exe)]"
EOF

cat > main.c << 'EOF'
#include <stdio.h>
#include "util.h"

int main(void)
{
    printf("add(2, 3) = %d\n", add(2, 3));
    return 0;
}
EOF

cat > util.c << 'EOF'
#include "util.h"

int add(int a, int b)
{
    return a + b;
}
EOF

cat > util.h << 'EOF'
int add(int a, int b);
EOF

mingw32-make -n            # 只打印将要执行的命令，不执行
mingw32-make status        # -n 之后：没有任何产物产生
mingw32-make               # 真正构建
mingw32-make status
mingw32-make               # 已是最新
mingw32-make -B            # 无条件重建：忽略时间戳，全部重编
mingw32-make status
